/**
 * Test flow for lookUpRecords action
 * Demonstrates looking up multiple records
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testLookUpRecords = Flow(
    {
        $id: Now.ID['test_look_up_records_flow'],
        name: 'Test Look Up Records',
        description: 'Tests the lookUpRecords core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_look_up_records_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.lookUpRecords,
            { $id: Now.ID['test_look_up_records_action'] },
            {
                table: 'incident',
                conditions: 'active=true^priority=1',
                max_results: 10,
                sort_column: 'priority',
                sort_type: 'sort_asc',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_look_up_records_log'] },
            {
                log_level: 'info',
                log_message: `lookUpRecords outputs: records=${wfa.dataPill(result.Records, 'reference')}, count=${wfa.dataPill(result.Count, 'integer')}, table=${wfa.dataPill(result.Table, 'string')}`,
            }
        )
    }
)
